package com.mockarena.evaluation.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="coding_evaluation_jobs",schema="evaluation") public class CodingEvaluationJob {
 @Id private UUID jobId; @Column(nullable=false,updatable=false) private UUID attemptId; @Column(nullable=false,updatable=false) private int globalPosition; @Column(nullable=false,updatable=false) private UUID questionId; @Column(nullable=false,updatable=false) private UUID questionVersionId; @Column(updatable=false,length=64) private String submittedResponseFingerprint; @Column(updatable=false,length=64) private String programmingLanguage; @Enumerated(EnumType.STRING) @Column(nullable=false) private CodingEvaluationJobStatus status; @Column(nullable=false) private int retryCount; @Column(nullable=false) private Instant nextAttemptAt; private String leaseOwner; private Instant leaseExpiresAt; private String lastFailureCategory; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; private String candidateFailureCategory; private Integer testsPassed; private Integer testsTotal; private Long executionTimeMs; private String resultOutcome; private java.math.BigDecimal awardedScore,maxScore; @Version private long version;
 protected CodingEvaluationJob(){} private CodingEvaluationJob(UUID id,UUID attemptId,int position,UUID questionId,UUID versionId,String fingerprint,String language,Instant now){this.jobId=id;this.attemptId=attemptId;globalPosition=position;this.questionId=questionId;questionVersionId=versionId;submittedResponseFingerprint=fingerprint;programmingLanguage=language;status=CodingEvaluationJobStatus.RECEIVED;nextAttemptAt=now;createdAt=now;updatedAt=now;}
 public static CodingEvaluationJob received(UUID attemptId,int position,UUID questionId,UUID versionId,String fingerprint,String language,Instant now){return new CodingEvaluationJob(UUID.randomUUID(),attemptId,position,questionId,versionId,fingerprint,language,now);}
 public void claim(String owner,Instant until,Instant now){status=CodingEvaluationJobStatus.RESOLVING_SPEC;leaseOwner=owner;leaseExpiresAt=until;updatedAt=now;}
 public void readyForRunner(Instant now){status=CodingEvaluationJobStatus.READY_FOR_RUNNER;leaseOwner=null;leaseExpiresAt=null;lastFailureCategory=null;updatedAt=now;}
 public void running(String owner,Instant until,Instant now){status=CodingEvaluationJobStatus.RUNNING;leaseOwner=owner;leaseExpiresAt=until;updatedAt=now;}
 public void runnerCompleted(String category,int passed,int total,Long duration,Instant now){status=CodingEvaluationJobStatus.READY_FOR_RESULT_APPLICATION;candidateFailureCategory=category;testsPassed=passed;testsTotal=total;executionTimeMs=duration;leaseOwner=null;leaseExpiresAt=null;lastFailureCategory=null;updatedAt=now;}
 public void derive(String outcome,java.math.BigDecimal awarded,java.math.BigDecimal max,Instant now){if(max.signum()<=0||awarded.signum()<0||awarded.compareTo(max)>0)throw new IllegalArgumentException();resultOutcome=outcome;awardedScore=awarded;maxScore=max;status=CodingEvaluationJobStatus.READY_FOR_RESULT_APPLICATION;leaseOwner=null;leaseExpiresAt=null;updatedAt=now;}
 public void readyForResultApplication(Instant now){status=CodingEvaluationJobStatus.READY_FOR_RESULT_APPLICATION;leaseOwner=null;leaseExpiresAt=null;lastFailureCategory=null;updatedAt=now;}
 public void completed(Instant now){status=CodingEvaluationJobStatus.COMPLETED;leaseOwner=null;leaseExpiresAt=null;lastFailureCategory=null;updatedAt=now;}
 public void retry(String category,Instant next,Instant now){status=CodingEvaluationJobStatus.RETRY_WAIT;retryCount++;nextAttemptAt=next;leaseOwner=null;leaseExpiresAt=null;lastFailureCategory=category;updatedAt=now;}
 public void fail(String category,Instant now){status=CodingEvaluationJobStatus.FAILED_INFRASTRUCTURE;leaseOwner=null;leaseExpiresAt=null;lastFailureCategory=category;updatedAt=now;}
 public UUID jobId(){return jobId;} public UUID attemptId(){return attemptId;} public int globalPosition(){return globalPosition;} public UUID questionId(){return questionId;} public UUID questionVersionId(){return questionVersionId;} public String submittedResponseFingerprint(){return submittedResponseFingerprint;} public String programmingLanguage(){return programmingLanguage;} public CodingEvaluationJobStatus status(){return status;} public int retryCount(){return retryCount;} public Instant nextAttemptAt(){return nextAttemptAt;} public String lastFailureCategory(){return lastFailureCategory;} public String candidateFailureCategory(){return candidateFailureCategory;} public Integer testsPassed(){return testsPassed;} public Integer testsTotal(){return testsTotal;} public Long executionTimeMs(){return executionTimeMs;} public String resultOutcome(){return resultOutcome;} public java.math.BigDecimal awardedScore(){return awardedScore;} public java.math.BigDecimal maxScore(){return maxScore;}
}
